package org.agentfrc.lesson;
import java.util.*;import edu.wpi.first.math.system.plant.DCMotor;import edu.wpi.first.wpilibj.simulation.*;
/** Prescribed-contact 1D transport experiment; native sleeve inertia, not calibrated grasp or scoring. */
public final class SeasonRollerRig implements AutoCloseable {
 public record Config(int season,String type,double mass,double radius,double inertia,double gear,int motors,double outer,double inner,double length,double window,double start,double normal,double mu,double beam){
  public Config {if(!Set.of(2024,2025,2026).contains(season)||!Set.of("NOTE","CORAL","FUEL").contains(type)||!Double.isFinite(gear)||gear<.1||gear>100||motors<1||motors>4||!Double.isFinite(outer)||outer<=0||outer>1||!Double.isFinite(inner)||inner<0||inner>=outer||!Double.isFinite(length)||length<0||length>1||!Double.isFinite(window)||window<=0||window>.5||!Double.isFinite(start)||start<=-window||start>=window||!Double.isFinite(beam)||beam<outer+start||beam>2)throw new IllegalArgumentException("Closed bounded experiment domain");new PrescribedRollerContact(mass,radius,inertia,mu,normal);}
 }
 public record Sample(double x,double velocity,double topOmega,double bottomOmega,double topMeasured,double bottomMeasured,double bus,double amps,double force,double contactLoss,double mechanicalResidual,boolean beam,int pulses,boolean done,boolean timeout){}
 public final Config c;public final SeasonRollerController controller;private final EncoderSim upper,lower;private final PWMSim top,bottom;private final DIOSim beam;private final DCMotor motor;private final PrescribedRollerContact active,open;private double x,v,wt,wb,at,ab,work,loss,bus=12,current,force;private final double scale;private final int beamFault;
 public SeasonRollerRig(Config c,double encoderScale,int beamFault){if(!Double.isFinite(encoderScale)||Math.abs(encoderScale)>2||encoderScale==0||beamFault<0||beamFault>2)throw new IllegalArgumentException("Fault fixture domain");this.c=c;this.scale=encoderScale;this.beamFault=beamFault;controller=new SeasonRollerController(c.radius,c.type.equals("NOTE")?2:1);upper=EncoderSim.createForChannel(0);lower=EncoderSim.createForChannel(2);top=new PWMSim(0);bottom=new PWMSim(1);beam=new DIOSim(6);motor=DCMotor.getNEO(c.motors);active=new PrescribedRollerContact(c.mass,c.radius,c.inertia,c.mu,c.normal);open=new PrescribedRollerContact(c.mass,c.radius,c.inertia,0,0);x=c.start;inject();}
 public static boolean occupied(Config c,double x){return switch(c.type){case "NOTE"->x>=c.beam-c.outer&&x<=c.beam+c.outer&&(x<=c.beam-c.inner||x>=c.beam+c.inner);case "CORAL"->x>=c.beam-c.length/2&&x<=c.beam+c.length/2;case "FUEL"->x>=c.beam-c.outer&&x<=c.beam+c.outer;default->throw new IllegalArgumentException("Shape");};}
 private void inject(){// Physical raw counts have an independent 2048 counts/revolution fixture.
  upper.setCount((int)Math.round(at/(2*Math.PI/2048)*scale));lower.setCount((int)Math.round(ab/(2*Math.PI/2048)));boolean blocked=beamFault==1||beamFault==0&&occupied(c,x);beam.setValue(!blocked);
 }
 public Sample step(boolean enabled,int substeps){if(substeps<20||substeps>200||200%substeps!=0)throw new IllegalArgumentException("Substeps");double dt=.02/substeps;if(dt*c.gear*c.gear*motor.KtNMPerAmp/(motor.rOhms*motor.KvRadPerSecPerVolt*c.inertia)>.25)throw new IllegalArgumentException("Explicit rotor stiffness domain");RoboRioSim.setVInVoltage(bus);controller.periodic(enabled);
  for(int k=0;k<substeps;k++){double[] d={top.getSpeed(),bottom.getSpeed()},e={wt*c.gear/motor.KvRadPerSecPerVolt,wb*c.gear/motor.KvRadPerSecPerVolt};var supply=SharedSupply.solve(12,.02,d,e,new double[]{motor.rOhms,motor.rOhms});bus=supply.volts();current=supply.batteryAmps();double tt=c.gear*motor.KtNMPerAmp*supply.armatureAmps()[0],tb=c.gear*motor.KtNMPerAmp*supply.armatureAmps()[1];double ft=wt+tt*dt/c.inertia,fb=wb+tb*dt/c.inertia;work+=tt*dt*(wt+ft)/2+tb*dt*(wb+fb)/2;boolean engaged=Math.abs(x)<c.window;var r=(engaged?active:open).resolve(v,-ft,fb,dt);v=r.velocity();wt=-r.leftOmega();wb=r.rightOmega();loss+=r.lossJ();force=(r.leftImpulse()+r.rightImpulse())/dt;x+=v*dt;at+=wt*dt;ab+=wb*dt;if(!Double.isFinite(x)||Math.abs(x)>20||Math.abs(v)>20)throw new IllegalStateException("Transport state domain");}
  inject();return new Sample(x,v,wt,wb,controller.upperRate(),controller.lowerRate(),bus,current,force,loss,active.kinetic(v,-wt,wb)+loss-work,occupied(c,x),controller.pulses(),controller.done(),controller.timedOut());
 }
 @Override public void close(){controller.close();}
}
